// === Tab: Particle ===
class Particle {

	constructor(location) {
		this.location = location.copy();
		this.acceleration = new p5.Vector(random(-0.5, 0.5), random(-0.5, 0.5));
		this.velocity = new p5.Vector(random(-0.75, 0.75), random(-0.75, 0.75));
		this.angle = 0;
		this.aVelocity = random(-0.1, 0.1);
		this.lifespan = 1024;
		this.s = 12;
	}

	update() {
		this.velocity.add(this.acceleration);
		this.location.add(this.velocity);
		this.acceleration.mult(0);
		this.angle += this.aVelocity;
		this.lifespan -= 2.0;
	}

	display() {
		noStroke();
		fill(175, this.lifespan);
		circle(this.location.x, this.location.y, 8);
	}

	run() {
		this.update();
		this.display();
	}

	isDead() {
		return this.lifespan < 0.0;
	}
}

// === Tab: ParticleSystem ===
class ParticleSystem {

	constructor(origin) {
		this.origin = origin.copy();
		this.particles = []
	}

	addParticle() {
		let r = int(random(14)); //r indirectly regulates the generation rate of new particles
		switch (r) {
			case 0:
				this.particles.push(new IShape(this.origin));
				break;
			case 1:
				this.particles.push(new JShape(this.origin));
				break;
			case 2:
				this.particles.push(new LShape(this.origin));
				break;
			case 3:
				this.particles.push(new OShape(this.origin));
				break;
			case 4:
				this.particles.push(new ZShape(this.origin));
				break;
			case 5:
				this.particles.push(new TShape(this.origin));
				break;
			case 6:
				this.particles.push(new SShape(this.origin));
				break;
		}
	}

	run() {
		this.particles = this.particles.filter((p) => !p.isDead())
		this.particles.map(p => p.run())
	}
}

// === Tab: Pieces ===
class IShape extends Particle {

	constructor(pos) {
		super(pos);
	}

	display() {
		let s = this.s
		noStroke();
		fill(color('#2BACE2'));
		push();
		translate(this.location.x + s / 2, this.location.y + 2 * s);
		rotate(this.angle);
		rectMode(CENTER);
		rect(0, 0, s, 4 * s);
		pop();
	}
}

class JShape extends Particle {

	constructor(pos) {
		super(pos);
	}

	display() {
		var s = this.s
		noStroke();
		fill(color('#0341AE'));
		push();
		translate(this.location.x, this.location.y);
		rotate(this.angle);
		beginShape();
		vertex(-s, 0.5 * s);
		vertex(-s, 1.5 * s);
		vertex(s, 1.5 * s);
		vertex(s, -1.5 * s);
		vertex(0, -1.5 * s);
		vertex(0, 0.5 * s);
		endShape(CLOSE);
		pop();
	}
}

